BEGIN TRANSACTION;
CREATE TABLE eg_drugs ("id" INTEGER PRIMARY KEY, "name" TEXT, "arabic" TEXT, "active" TEXT, "company" TEXT, "price" TEXT, "oldprice" TEXT, "barcode" TEXT, "barcode_valid" TEXT, "slug" TEXT, "units" TEXT, "description" TEXT, "uses" TEXT);
CREATE INDEX idx_eg_drugs_name ON eg_drugs(name);
CREATE INDEX idx_eg_drugs_arabic ON eg_drugs(arabic);
CREATE INDEX idx_eg_drugs_active ON eg_drugs(active);
CREATE INDEX idx_eg_drugs_barcode ON eg_drugs(barcode);
COMMIT;
