INSERT INTO "eg_drugs" VALUES(3335,'zitless gel 50 gm','زيتلس جل 50 جرام','','alpha group','30','','','0','zitless-gel-50-gm','1','acne products','لعلاج حب الشباب زيتلس جيل ( Zit less ) - لعلاج حب الشباب - معتمد من وزارة الصحة - جيل زيتلس بيركز على مكان الحباية و غير منتشر لباقى الجلد . - جيل زيتلس يعطى كفاءة عالية و نتيجة فعالة و قوية لمعلاجة حب الشباب و عدم ترك أى أثر بعد العلاج - زيتلس جيل لنقاء البشرة من حب الشباب من A-------Z - زيتلس جيل يحتوى على مادة فعالة قوية لأزالة حب الشباب بجميع درجاته - زيتلس جيل لا يسبب تهيج للبشرة و لا جفاف . زيتلس جيل يحتوى على مضادات للألتهابات تحمى البشرة من التهيج و يحتوى على مرطبات للبشرة تمنع جفافها . - زيتلس جيل يحتوى على عدد (6) من مرطبات البشرة تجعل البشرة أكثر نقادا و حيوية . - زيتلس جيل ليس له أى أى أضرار جانبية و ليس له أى تفاعل مع أى أدوية أخرى و يصرح بأخذه مع أى علاج أخر . - زيتلس جيل موضعى وليس أى أثر على من أجهزة الجسم الأخرى - زيتلس جيل يستخدم مرتين يوميا بعد أستخدام أى غسول للبشرة .');
