INSERT INTO "eg_drugs" VALUES(10658,'cholaflux 50 mg 30 f.c. tabs','كولافلاكس 50مجم 30 قرص','eplerenone','egpi','297','','','0','cholaflux-50-mg-30-f.c.-tabs','3','aldosterone receptor antagonist','لتقليل ضغط الدم المرتفع وتحسين حالة المرضى المصابين بفشل القلب بعد التعرض لنوبة قلبية حيث تمنع تراكم السوائل والصوديوم في الجسم. يساعد الدواء في حماية القلب والأوعية الدموية من التليف والضرر الناتج عن زيادة هرمون الألدوستيرون.');
