INSERT INTO "eg_drugs" VALUES(30953,'movelex plus massage gel 100 gm','موفيليكس بلس مساج جل 100 جم','magnesium','nikim > majestic biopharma','180','150','6224010938151','1','movelex-plus-massage-gel-100-gm','1','massage','');
INSERT INTO "eg_drugs" VALUES(30954,'moventor 30 tabs','موفينتور 30 قرص','undenatured collagen type ii-hyaluronic acid -boron','copad pharma','585','435','2203017340116','1','moventor-30-tabs','3','anti rheumatic.osteoarthritis.anabolic agent','علاج التهابات وخشونة المفاصل. -- تعويض المادة التي تحمي العظام من التآكل. -- تقليل احتكاك العظام وتقليل الألم. -- يحتوي الكولاجين النوع 2 و الهيالويورونيك والبورون. -- موفينتور - MOVENTOR   يُعتقد أن العديد من المكملات الغذائية تساعد في تخفيف آلام المفاصل، من الجلوكوزامين إلى أحماض أوميجا 3 الدهنية، حيث يساعد الجلوكوزامين في الحفاظ على صحة النقل في المفاصل وله تأثير مضاد للالتهابات، وقد ثبت أن كوندرويتين يقلل الألم ويزيد من حركة المفاصل، وقد تساعد أحماض أوميجا 3 الدهنية في تخفيف التيبس، ولكن في السنوات الأخيرة، اكتسب الكولاجين شعبية، خاصة أنه يوجد بشكل طبيعي في العظام والعضلات والجلد والأوتار، ويمكن أن يكون عاملاً رئيسيًا في التخلص من مشاكل المفاصل.  من جانبه، أوضح طبيب بتقويم العمود الفقري ومؤسس Adio، إكسندر، أن الكولاجين هو بروتين يشكل مكونًا حيويًا من الأنسجة الضامة ويساعد في تكوين الغضروف الذي يبطن مفاصلنا، ومع مرور الوقت والتقدم فى السن، يتفكك الكولاجين في الجسم مما قد يؤثر على صحة المفاصل والجلد.  وأضاف الدكتور إكسندر "أجد عمليًا أن وجود كمية كافية من الكولاجين في النظام الغذائي يساعد على تحسين قدرة المرضى على الشفاء من مشاكل المفاصل، إنه جيد بشكل عام لمشاكل الركبة والورك لأنها أكبر وتحمل الأثقال أثناء المشي ولكنها ضرورية لصحة العمود الفقري أيضًا".  وتابع "يوجد بين فقرات العمود الفقري أقراص تتكون بشكل كبير من الغضاريف والماء، ونظرًا لأنني أعالج العديد من الحالات المتعلقة بإصابات القرص الغضروفى وغيرها، فإنني أوصي دائمًا بتناول غذاء جيد من الكولاجين، إلى جانب علاج مفاصل العمود الفقري".  على الجانب الآخر، قالت صوفي ميدلين، أخصائية التغذية المسجلة ورئيسة جمعية الحمية البريطانية في لندن، إنه لا يوجد حاليًا سوى القليل من الأدلة على فوائد الكولاجين في حالات المفاصل مثل التهاب المفاصل، ولكن هناك مجموعة متزايدة من الأدلة على أن مكملات الكولاجين يمكن أن تحسن قوة المفاصل وثباتها.  وأضافت "مكملات الكولاجين تبدو قادرة على تقديم الدعم للأربطة والغضاريف والأوتار، مما قد يساعد في إصلاح الإصابات وتقليل احتمالية تكرار الإصابة، ولدينا أيضًا بعض البيانات التي تُظهر أن مكملات الكولاجين قد تحسن كثافة العظام".  وقد أظهرت بعض الدراسات أن تناول مكملات الكولاجين قد يساعد في تحسين أعراض هشاشة العظام وتقليل آلام المفاصل بشكل عام.');
